<?php
/** Responsible AI: bias and fairness, privacy and personal data, copyright, transparency and the EU AI Act, safe everyday use. */

return [
    'id' => 'ai-ethics', 'family' => 'ai', 'after' => 'ai-base',
    'title' => L('AI responsabile e privacy', 'Responsible AI and Privacy'), 'short' => L('AI responsabile', 'Responsible AI'), 'level' => L('Base', 'Basics'),
    'desc' => L('Usare l’AI senza fare danni: bias ed equità, dati personali, diritto d’autore, trasparenza, AI Act europeo e buone abitudini quotidiane.', 'Using AI without causing harm: bias and fairness, personal data, copyright, transparency, the EU AI Act and good everyday habits.'),
    'lessons' => [
        lesson('bias', L('Bias ed equità', 'Bias and fairness'), [
            P('Un modello impara dai dati, compresi i loro **pregiudizi**. Se in passato un’azienda ha assunto soprattutto uomini, un modello addestrato su quei curriculum può penalizzare le donne. Questo è un **bias**: un errore sistematico che svantaggia un gruppo.', 'A model learns from data, prejudices included. If a company mostly hired men in the past, a model trained on those CVs may penalise women. That is a **bias**: a systematic error that disadvantages a group.'),
            P('Le difese: dati rappresentativi, misurare gli errori **per gruppo** (non solo in media), togliere variabili sensibili *e* quelle che le sostituiscono (il CAP può rivelare l’origine), e tenere una persona nel giro per le decisioni importanti.', 'Defences: representative data, measuring errors **per group** (not just on average), removing sensitive variables *and* their proxies (a postcode can reveal origin), and keeping a person in the loop for important decisions.'),
        ], [
            Q('b1', L('Da dove nasce più spesso un bias?', 'Where does bias most often come from?'), [L('Dai dati di addestramento', 'From the training data'), L('Dal colore del logo', 'From the logo colour'), L('Dalla velocità del server', 'From server speed'), L('Dal numero di utenti', 'From the number of users')], 0, L('Il modello riflette i dati.', 'The model mirrors the data.')),
            Q('b2', L('Perché misurare gli errori per gruppo?', 'Why measure errors per group?'), [L('Una buona media può nascondere un gruppo svantaggiato', 'A good average can hide a disadvantaged group'), L('Per fare più grafici', 'To make more charts'), L('È più veloce', 'It is faster'), L('Non serve', 'It is not needed')], 0, L('L’equità si vede nei dettagli.', 'Fairness shows in the details.')),
            Q('b3', L('Che cos’è una variabile “proxy”?', 'What is a “proxy” variable?'), [L('Una che rivela indirettamente un dato sensibile', 'One that indirectly reveals a sensitive attribute'), L('Un server intermedio', 'An intermediate server'), L('Una password', 'A password'), L('Un tipo di grafico', 'A type of chart')], 0, L('Per esempio il CAP.', 'For example the postcode.')),
        ], task('text', L('Elenca due modi per ridurre il bias, uno per riga, che inizino con `-`.', 'List two ways to reduce bias, one per line, starting with `-`.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due misure', 'Two measures')), re('dati|data|grupp|group|umano|human|person', L('Parli di dati, gruppi o controllo umano', 'You mention data, groups or human oversight'))], '', "- usare dati rappresentativi di tutti i gruppi\n- misurare gli errori separatamente per ogni gruppo"), [
            dMatch(pMatch(), [['Bias', L('Errore sistematico verso un gruppo', 'Systematic error against a group')], ['Proxy', L('Variabile che rivela un dato sensibile', 'Variable revealing a sensitive attribute')], [L('Dati rappresentativi', 'Representative data'), L('Tutti i gruppi presenti', 'All groups present')], [L('Persona nel giro', 'Human in the loop'), L('Decide nei casi importanti', 'Decides important cases')]], L('Il lessico dell’equità.', 'The vocabulary of fairness.')),
            dFlash(pFlash(), [[L('Un modello può essere ingiusto senza che nessuno lo voglia', 'A model can be unfair without anyone intending it'), true], [L('Togliere il campo “genere” elimina sempre il bias', 'Removing the “gender” field always removes bias'), false], [L('Una buona accuratezza media basta', 'Good average accuracy is enough'), false], [L('I dati storici possono contenere discriminazioni', 'Historical data can contain discrimination'), true]], L('L’equità va misurata.', 'Fairness must be measured.')),
        ]),
        lesson('privacy', L('Dati personali e privacy', 'Personal data and privacy'), [
            P('Quello che scrivi in un chatbot può essere conservato, letto per sicurezza o, secondo le impostazioni, usato per addestrare modelli futuri. Prima di incollare dati, controlla la **policy** del servizio e le impostazioni di privacy.', 'What you type into a chatbot may be stored, reviewed for safety or, depending on settings, used to train future models. Before pasting data, check the service’s **policy** and privacy settings.'),
            P('Non inserire dati personali di altri, password, dati sanitari o segreti aziendali in servizi non approvati. In Europa vale il **GDPR**: servono una base legale, il minimo indispensabile di dati e trasparenza verso le persone coinvolte. Quando puoi, **anonimizza** (togli nomi, email, numeri).', 'Do not enter other people’s personal data, passwords, health data or company secrets into unapproved services. In Europe the **GDPR** applies: you need a legal basis, the minimum necessary data and transparency towards the people involved. When you can, **anonymise** (remove names, emails, numbers).'),
        ], [
            Q('p1', L('Che cosa non andrebbe incollato in un chatbot pubblico?', 'What should not be pasted into a public chatbot?'), [L('La password di un collega', 'A colleague’s password'), L('Una ricetta della nonna', 'Grandma’s recipe'), L('Una poesia di Leopardi', 'A Leopardi poem'), L('Un esercizio di matematica', 'A maths exercise')], 0, L('Segreti e dati altrui restano fuori.', 'Secrets and others’ data stay out.')),
            Q('p2', L('Che cosa significa anonimizzare?', 'What does anonymising mean?'), [L('Togliere ciò che identifica le persone', 'Removing what identifies people'), L('Cifrare il computer', 'Encrypting the computer'), L('Cambiare nome utente', 'Changing username'), L('Usare la modalità scura', 'Using dark mode')], 0, L('Nomi, email, numeri, indirizzi.', 'Names, emails, numbers, addresses.')),
            Q('p3', L('Quale principio chiede il GDPR?', 'Which principle does the GDPR require?'), [L('Usare il minimo di dati necessario', 'Using the minimum data necessary'), L('Raccogliere più dati possibile', 'Collecting as much data as possible'), L('Pubblicare i dati', 'Publishing the data'), L('Nessuna regola', 'No rules')], 0, L('Minimizzazione dei dati.', 'Data minimisation.')),
        ], task('text', L('Anonimizza questo testo sostituendo nome, email e telefono con `[NOME]`, `[EMAIL]` e `[TELEFONO]`: “Mario Rossi (mario.rossi@example.com, 333 1234567) chiede un rimborso.”', 'Anonymise this text replacing name, email and phone with `[NOME]`, `[EMAIL]` and `[TELEFONO]`: “Mario Rossi (mario.rossi@example.com, 333 1234567) asks for a refund.”'), 'Mario Rossi (mario.rossi@example.com, 333 1234567) chiede un rimborso.', [re('\[NOME\]', L('Il nome è nascosto', 'The name is hidden')), re('\[EMAIL\]', L('L’email è nascosta', 'The email is hidden')), re('\[TELEFONO\]', L('Il telefono è nascosto', 'The phone is hidden')), re('(?<![\s\S])(?![\s\S]*(Rossi|@example|1234567))', L('Non resta nessun dato originale', 'No original data is left'))], '', '[NOME] ([EMAIL], [TELEFONO]) chiede un rimborso.'), [
            dBug(pBug(), ['reclamo = {', '  cliente: "[NOME]",', '  email: "[EMAIL]",', '  carta: "4111 1111 1111 1111",', '  problema: "pacco mai arrivato"', '}'], 3, '  carta: "[CARTA]",', L('Il numero di carta va tolto prima di incollare.', 'The card number must be removed before pasting.')),
            dFlash(pFlash(), [[L('Alcuni servizi usano le chat per addestrare i modelli', 'Some services use chats to train models'), true], [L('Incollare dati sanitari altrui è sempre lecito', 'Pasting others’ health data is always fine'), false], [L('Conviene leggere le impostazioni di privacy', 'It pays to read the privacy settings'), true], [L('Il GDPR non riguarda l’AI', 'The GDPR does not apply to AI'), false]], L('I dati delle persone vanno protetti.', 'People’s data must be protected.')),
        ]),
        lesson('copyright', L('Diritto d’autore e originalità', 'Copyright and originality'), [
            P('Chi possiede un testo o un’immagine generati dall’AI? Le regole variano da paese a paese e stanno ancora cambiando. In molti ordinamenti un’opera è protetta solo se c’è un **contributo creativo umano** significativo.', 'Who owns a text or image generated by AI? The rules vary by country and are still evolving. In many legal systems a work is protected only when there is a significant **human creative contribution**.'),
            P('Buone pratiche: non chiedere di copiare opere protette o lo stile riconoscibile di un artista vivente per scopi commerciali, controlla le **condizioni d’uso** del servizio, verifica che il codice generato non riproduca codice con licenze incompatibili, e dichiara l’uso dell’AI quando è richiesto (scuola, editori, concorsi).', 'Good practice: do not ask to copy protected works or a living artist’s recognisable style for commercial use, check the service’s **terms of use**, verify generated code does not reproduce code under incompatible licences, and disclose AI use when required (school, publishers, contests).'),
        ], [
            Q('r1', L('In molti paesi, quando un’opera generata è protetta?', 'In many countries, when is a generated work protected?'), [L('Se c’è un contributo creativo umano', 'When there is human creative contribution'), L('Sempre', 'Always'), L('Mai, in nessun caso', 'Never, in any case'), L('Solo se è lunga', 'Only if it is long')], 0, L('E le regole cambiano ancora.', 'And the rules are still changing.')),
            Q('r2', L('Che cosa controllare nel codice generato?', 'What should you check in generated code?'), [L('Che non copi codice con licenze incompatibili', 'That it does not copy code with incompatible licences'), L('Che abbia tanti commenti', 'That it has many comments'), L('Che sia colorato', 'That it is colourful'), L('Niente', 'Nothing')], 0, L('Le licenze contano anche per l’AI.', 'Licences matter for AI too.')),
            Q('r3', L('Quando dichiarare l’uso dell’AI?', 'When should you disclose AI use?'), [L('Quando è richiesto da scuola, editore o regolamento', 'When school, publisher or rules require it'), L('Mai', 'Never'), L('Solo il lunedì', 'Only on Mondays'), L('Solo per le immagini', 'Only for images')], 0, L('La trasparenza evita problemi.', 'Transparency avoids trouble.')),
        ], task('text', L('Scrivi una breve nota di trasparenza (una o due frasi) da mettere in fondo a un articolo scritto con l’aiuto dell’AI e rivisto da te.', 'Write a short transparency note (one or two sentences) to put at the end of an article written with AI help and reviewed by you.'), '', [re('\bAI\b|\bIA\b|intelligenza artificiale|artificial intelligence', L('Citi l’AI', 'You mention AI')), re('rivist|revisionat|controllat|verificat|review|checked|edited', L('Dici che l’hai rivisto', 'You say you reviewed it'))], '', 'Questo articolo è stato scritto con l’aiuto di uno strumento di AI e rivisto e verificato dall’autore.'), [
            dMatch(pMatch(), [[L('Contributo umano', 'Human contribution'), L('Base della tutela', 'Basis for protection')], [L('Condizioni d’uso', 'Terms of use'), L('Cosa permette il servizio', 'What the service allows')], [L('Licenza', 'Licence'), L('Regole d’uso del codice', 'Rules for using code')], [L('Nota di trasparenza', 'Transparency note'), L('Dichiara l’uso dell’AI', 'Discloses AI use')]], L('Creare con l’AI in modo corretto.', 'Creating with AI correctly.')),
            dFlash(pFlash(), [[L('Le regole sul diritto d’autore e l’AI sono uguali ovunque', 'Copyright rules on AI are the same everywhere'), false], [L('Il codice generato può riprodurre codice esistente', 'Generated code can reproduce existing code'), true], [L('Le condizioni d’uso del servizio contano', 'The service’s terms of use matter'), true], [L('Dichiarare l’uso dell’AI è vietato', 'Disclosing AI use is forbidden'), false]], L('Trasparenza e rispetto.', 'Transparency and respect.')),
        ]),
        lesson('ai-act', L('L’AI Act europeo', 'The EU AI Act'), [
            P('L’**AI Act** è il regolamento europeo sull’intelligenza artificiale, entrato in vigore nel 2024 e applicato a tappe. Classifica i sistemi per **livello di rischio**: inaccettabile (vietati), alto, limitato, minimo.', 'The **AI Act** is the EU regulation on artificial intelligence, in force since 2024 and applied in stages. It classifies systems by **risk level**: unacceptable (banned), high, limited, minimal.'),
            C('Inaccettabile  punteggio sociale dei cittadini, manipolazione → vietati
Alto           selezione del personale, credito, istruzione → requisiti rigorosi
Limitato       chatbot, contenuti generati → obblighi di trasparenza
Minimo         filtri antispam, videogiochi → nessun obbligo specifico', 'text'),
            P('Per i sistemi ad alto rischio servono gestione del rischio, dati di qualità, documentazione, supervisione umana. Per i chatbot e i contenuti generati l’obbligo principale è la **trasparenza**: le persone devono sapere che parlano con una macchina e che un contenuto è artificiale.', 'High-risk systems need risk management, quality data, documentation and human oversight. For chatbots and generated content the main duty is **transparency**: people must know they are talking to a machine and that content is artificial.'),
        ], [
            Q('a1', L('Su che cosa si basa l’AI Act?', 'What is the AI Act based on?'), [L('Livelli di rischio', 'Risk levels'), L('La dimensione dell’azienda', 'Company size'), L('Il prezzo del servizio', 'The service price'), L('Il linguaggio di programmazione', 'The programming language')], 0, L('Più rischio, più obblighi.', 'More risk, more duties.')),
            Q('a2', L('Il punteggio sociale dei cittadini è…', 'Social scoring of citizens is…'), [L('Vietato', 'Banned'), L('Rischio minimo', 'Minimal risk'), L('Senza obblighi', 'Without duties'), L('Consigliato', 'Recommended')], 0, L('Rischio inaccettabile.', 'Unacceptable risk.')),
            Q('a3', L('Quale obbligo principale ha un chatbot?', 'What is a chatbot’s main duty?'), [L('Dire che è una macchina', 'Saying it is a machine'), L('Essere gratuito', 'Being free'), L('Rispondere in latino', 'Answering in Latin'), L('Nessuno', 'None')], 0, L('Trasparenza.', 'Transparency.')),
        ], task('text', L('Classifica tre sistemi secondo l’AI Act, uno per riga come `sistema: rischio`. Sistemi: `filtro antispam`, `selezione dei curriculum`, `chatbot di assistenza`. Rischi: minimo, alto, limitato.', 'Classify three systems under the AI Act, one per line as `system: risk`. Systems: `spam filter`, `CV screening`, `support chatbot`. Risks: minimal, high, limited.'), '', [re('(antispam|spam)[^:\n]*:\s*(minimo|minimal)', L('Lo spam è rischio minimo', 'Spam is minimal risk')), re('(curricul|CV)[^:\n]*:\s*(alto|high)', L('La selezione è ad alto rischio', 'Screening is high risk')), re('chatbot[^:\n]*:\s*(limitato|limited)', L('Il chatbot è rischio limitato', 'The chatbot is limited risk'))], '', "filtro antispam: minimo\nselezione dei curriculum: alto\nchatbot di assistenza: limitato"), [
            dOrder(pSort(), [L('Inaccettabile', 'Unacceptable'), L('Alto', 'High'), L('Limitato', 'Limited'), L('Minimo', 'Minimal')], L('Dal più al meno rischioso.', 'From most to least risky.')),
            dMatch(pMatch(), [[L('Punteggio sociale', 'Social scoring'), L('Vietato', 'Banned')], [L('Selezione del personale', 'Recruitment'), L('Alto rischio', 'High risk')], ['Chatbot', L('Trasparenza', 'Transparency')], [L('Videogioco', 'Video game'), L('Rischio minimo', 'Minimal risk')]], L('Ogni sistema il suo livello.', 'Each system its level.')),
        ]),
        lesson('habits', L('Buone abitudini', 'Good habits'), [
            P('Qualche regola semplice per usare l’AI ogni giorno: **verifica** fatti, numeri e citazioni; **proteggi** dati tuoi e altrui; **dichiara** l’uso quando conta; **resta tu** il responsabile del risultato finale.', 'A few simple rules for everyday AI use: **verify** facts, numbers and quotes; **protect** your data and others’; **disclose** use when it matters; **stay** responsible for the final result.'),
            P('Attenzione anche ai **deepfake** (immagini, voci e video falsi): diffida di messaggi urgenti con voci conosciute che chiedono soldi o dati, e verifica sempre per un altro canale.', 'Watch out for **deepfakes** too (fake images, voices and videos): distrust urgent messages with familiar voices asking for money or data, and always verify through another channel.'),
            Tip('Una regola d’oro: non delegare all’AI una decisione che non sapresti spiegare o difendere tu.', 'A golden rule: do not delegate to AI a decision you could not explain or defend yourself.'),
        ], [
            Q('g1', L('Chi è responsabile di un testo pubblicato scritto con l’AI?', 'Who is responsible for a published text written with AI?'), [L('Chi lo pubblica', 'Whoever publishes it'), L('Il modello', 'The model'), L('Nessuno', 'Nobody'), L('Il fornitore di internet', 'The internet provider')], 0, L('Lo strumento non firma.', 'The tool does not sign.')),
            Q('g2', L('Ricevi un vocale urgente di un parente che chiede soldi: che fai?', 'You get an urgent voice message from a relative asking for money: what do you do?'), [L('Verifico chiamandolo su un altro canale', 'Verify by calling them on another channel'), L('Pago subito', 'Pay at once'), L('Inoltro a tutti', 'Forward it to everyone'), L('Rispondo con i dati della carta', 'Reply with card details')], 0, L('Le voci si possono clonare.', 'Voices can be cloned.')),
            Q('g3', L('Che cos’è un deepfake?', 'What is a deepfake?'), [L('Un contenuto falso realistico generato con l’AI', 'A realistic fake made with AI'), L('Un tipo di database', 'A kind of database'), L('Un antivirus', 'An antivirus'), L('Un errore di stampa', 'A typo')], 0, L('Immagini, voci, video.', 'Images, voices, videos.')),
        ], task('text', L('Scrivi la tua checklist personale per l’uso dell’AI: quattro righe che iniziano con `[ ]`, una sulla verifica e una sui dati.', 'Write your personal AI-use checklist: four lines starting with `[ ]`, one about verification and one about data.'), "[ ] \n[ ] \n[ ] \n[ ] ", [re('^\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S', L('Quattro voci', 'Four items')), re('verific|controll|check|verify', L('Una voce sulla verifica', 'An item on verification')), re('dati|privacy|personal|data', L('Una voce sui dati', 'An item on data'))], '', "[ ] verifico fatti e numeri importanti\n[ ] non inserisco dati personali di altri\n[ ] dichiaro l’uso dell’AI quando serve\n[ ] rileggo sempre prima di pubblicare"), [
            dMatch(pMatch(), [[L('Verifica', 'Verify'), L('Fatti, numeri, citazioni', 'Facts, numbers, quotes')], [L('Proteggi', 'Protect'), L('Dati tuoi e altrui', 'Your and others’ data')], [L('Dichiara', 'Disclose'), L('Uso dell’AI quando conta', 'AI use when it matters')], [L('Rispondi', 'Own it'), L('La responsabilità resta tua', 'Responsibility stays yours')]], L('Quattro abitudini.', 'Four habits.')),
            dFlash(pFlash(), [[L('Una voce al telefono può essere generata dall’AI', 'A voice on the phone can be AI-generated'), true], [L('Se l’ha scritto l’AI, la colpa non è mai tua', 'If AI wrote it, it is never your fault'), false], [L('Verificare per un altro canale protegge dalle truffe', 'Verifying through another channel protects from scams'), true], [L('Le immagini realistiche sono sempre vere', 'Realistic images are always real'), false]], L('Prudenza digitale.', 'Digital prudence.')),
        ]),
    ],
];
